    <script id="harmat-lakaskereso-unified-js-20260513">
    (function () {
      if (window.__harmatLakaskeresoUnifiedReady) return;
      window.__harmatLakaskeresoUnifiedReady = true;
      function norm(value) { return String(value || '').toLowerCase().trim(); }
      function floorSort(value) { value = String(value || '').trim(); if (!value || /^f(sz)?$/i.test(value)) return 0; var n = parseInt(value, 10); return isNaN(n) ? 99 : n; }
      function unique(list) { return Array.from(new Set(list.filter(Boolean))).sort(function(a,b){ return String(a).localeCompare(String(b), 'hu', { numeric:true }); }); }
      function statusKey(item) { var status = norm(item.status || item.statusLabel); if (status.indexOf('sold') !== -1 || status.indexOf('elad') !== -1) return 'sold'; if (status.indexOf('reserved') !== -1 || status.indexOf('foglal') !== -1) return 'reserved'; return 'current'; }
      function statusLabel(item) { var key = statusKey(item); if (key === 'sold') return 'Eladva'; if (key === 'reserved') return 'Foglalva'; return item.statusLabel || 'Elérhető'; }
      function priceLabel() { return 'Ár egyeztetés alapján'; }
      function sqmLabel() { return 'Érdeklődjön árainkról'; }
      function area(value) { var number = parseFloat(value) || 0; return number ? number.toLocaleString('hu-HU', { maximumFractionDigits: 2 }) + 'm²' : '-'; }
      function floorLabel(value) { value = String(value || '').trim(); return /^f(sz)?$/i.test(value) || value === '0' ? 'Fsz' : value; }
      function titleOf(item) { return item.title || [item.building, item.floor, item.unit || item.number].filter(Boolean).join('-'); }
      function bestFromSrcset(value) {
        value = String(value || '').trim();
        if (!value) return '';
        var best = { url: '', width: 0 };
        value.split(',').forEach(function(part){
          var bits = part.trim().split(/\s+/);
          var url = bits[0] || '';
          var width = parseInt((bits[1] || '').replace('w', ''), 10) || 0;
          if (url && width >= best.width) best = { url: url, width: width };
        });
        return best.url;
      }
      function usableImage(value) {
        value = String(value || '').trim();
        if (!value || /^data:image\/svg/i.test(value) || value.indexOf('blank.gif') !== -1) return '';
        return value;
      }
      function imageCandidates(img) {
        if (!img) return [];
        return [
          bestFromSrcset(img.getAttribute('data-srcset')),
          bestFromSrcset(img.getAttribute('srcset')),
          img.getAttribute('data-lazy-src'),
          img.getAttribute('data-src'),
          img.currentSrc,
          img.src
        ].map(usableImage).filter(Boolean);
      }
      function collectImages() {
        var byTitle = {}, byRooms = {}, first = '';
        document.querySelectorAll('.harmat-front-card, .property, .e-loop-item').forEach(function(card){
          var img = card.querySelector('img');
          var candidates = imageCandidates(img);
          var src = candidates[0] || '';
          if (!src) return;
          if (!first) first = src;
          var title = (card.dataset.harmatTitle || (card.querySelector('.harmat-front-badge') ? card.querySelector('.harmat-front-badge').textContent : '') || card.innerText || '').match(/A[1-4][\w-]*L\d/i);
          if (title) byTitle[title[0].toUpperCase()] = src;
          var room = card.dataset.harmatRooms || ((card.innerText || '').match(/\b([1-5])\s*(?:szoba|Szoba)\b/) || [])[1];
          if (room && !byRooms[room]) byRooms[room] = src;
        });
        return { byTitle: byTitle, byRooms: byRooms, first: first };
      }
      function imageFor(item, images) {
        var direct = usableImage(item.image) || usableImage(item.floorplan);
        return direct || images.byTitle[titleOf(item).toUpperCase()] || images.byRooms[String(item.rooms || '')] || images.first || 'https://harmat22.hu/wp-content/uploads/2026/02/Harmat22_latvany-12-800x800.jpg';
      }
      function sourceItems() {
        var apartments = Array.isArray(window.harmatUnifiedSalesData && window.harmatUnifiedSalesData.apartments) ? window.harmatUnifiedSalesData.apartments : [];
        if (apartments.length) return apartments.slice();
        var items = (window.harmatUnifiedSalesData && window.harmatUnifiedSalesData.items) || (window.harmatSalesFront && window.harmatSalesFront.items) || {};
        return Object.keys(items).map(function(id){ return items[id]; });
      }
      function cardHtml(item, images) {
        var key = statusKey(item);
        var title = titleOf(item);
        var img = imageFor(item, images);
        var href = key === 'sold' ? '#' : (item.url || item.link || '#');
        return '<article class="harmat-unified-card is-' + key + '" data-status="' + key + '" data-title="' + title.toLowerCase() + '" data-building="' + (item.building || '') + '" data-floor="' + (item.floor || '') + '" data-rooms="' + (item.rooms || '') + '">' +
          '<a class="harmat-unified-media" href="' + href + '">' + (img ? '<img src="' + img + '" alt="' + title + '">' : '<span class="harmat-unified-media-fallback">Harmat Lakópark</span>') + '</a>' +
          '<span class="harmat-unified-badge">' + title + ' · ' + statusLabel(item) + '</span>' +
          '<span class="harmat-unified-price"><strong>' + priceLabel(item) + '</strong><small>' + sqmLabel(item) + '</small></span>' +
          '<div class="harmat-unified-body"><div class="harmat-unified-meta harmat-unified-meta-main">' +
          '<div><h6>Épület</h6><p>' + (item.building || '-') + '</p></div><div><h6>Emelet</h6><p>' + floorLabel(item.floor) + '</p></div><div><h6>Szoba</h6><p>' + (item.rooms || '-') + '</p></div></div>' +
          '<div class="harmat-unified-meta harmat-unified-meta-area"><div><h6>Alapterület</h6><p>' + area(item.area || item.salesArea || item.b_area) + '</p></div><div><h6>Terasz/Erkély</h6><p>' + area(item.terrace || item.land || item.l_area) + '</p></div></div>' +
          '<a class="harmat-unified-btn" href="' + href + '">Megnézem</a></div></article>';
      }
      function render() {
        var data = sourceItems().sort(function(a,b){ return String(a.building || '').localeCompare(String(b.building || ''), 'hu') || floorSort(a.floor) - floorSort(b.floor) || String(a.unit || a.number || a.title || '').localeCompare(String(b.unit || b.number || b.title || ''), 'hu', { numeric:true }); });
        if (!data.length || document.querySelector('.harmat-unified-search')) return;
        var oldCards = Array.prototype.slice.call(document.querySelectorAll('.harmat-front-card'));
        if (!oldCards.length) return setTimeout(render, 500);
        var oldHost = oldCards[0].closest('.elementor-widget-loop-grid') || oldCards[0].parentElement;
        if (!oldHost || !oldHost.parentElement) return;
        var images = collectImages();
        document.querySelectorAll('.harmat-front-property-filter, .harmat-filter-empty').forEach(function(node){ node.remove(); });
        var buildings = unique(data.map(function(item){ return item.building; }));
        var floors = unique(data.map(function(item){ return floorLabel(item.floor); }));
        var rooms = unique(data.map(function(item){ return String(item.rooms || ''); }));
        function options(list) { return '<option value="">Mind</option>' + list.map(function(value){ return '<option value="' + String(value).replace(/"/g, '&quot;') + '">' + value + '</option>'; }).join(''); }
        var root = document.createElement('section');
        root.className = 'harmat-unified-search';
        root.innerHTML = '<div class="harmat-unified-filter"><div class="harmat-unified-head"><h3 class="harmat-unified-title">Lakáskereső</h3><span class="harmat-unified-count"></span></div>' +
          '<div class="harmat-unified-status"><button type="button" data-status="all">Mind</button><button type="button" data-status="current">Elérhető</button><button type="button" data-status="reserved">Foglalva</button><button type="button" data-status="sold">Eladva</button></div>' +
          '<div class="harmat-unified-fields"><label class="harmat-unified-field">Lakás száma<input type="search" data-filter="query" placeholder="pl. A1-F-L1"></label><label class="harmat-unified-field">Épület<select data-filter="building">' + options(buildings) + '</select></label><label class="harmat-unified-field">Emelet<select data-filter="floor">' + options(floors) + '</select></label><label class="harmat-unified-field">Szoba<select data-filter="rooms">' + options(rooms) + '</select></label><button class="harmat-unified-clear" type="button">Alaphelyzet</button></div></div>' +
          '<div class="harmat-unified-grid">' + data.map(function(item){ return cardHtml(item, images); }).join('') + '</div><div class="harmat-unified-empty">Nincs a feltételeknek megfelelő lakás. Kérjük, módosítsa a szűrést.</div>';
        oldHost.parentElement.insertBefore(root, oldHost);
        oldHost.remove();
        var state = { status:'all', query:'', building:'', floor:'', rooms:'' };
        var cards = Array.prototype.slice.call(root.querySelectorAll('.harmat-unified-card'));
        var count = root.querySelector('.harmat-unified-count');
        var empty = root.querySelector('.harmat-unified-empty');
        function apply() {
          root.querySelectorAll('[data-status]').forEach(function(btn){ btn.classList.toggle('is-active', btn.dataset.status === state.status); });
          var visible = 0;
          cards.forEach(function(card){
            var ok = (state.status === 'all' || card.dataset.status === state.status) && (!state.query || (card.dataset.title || '').indexOf(state.query) !== -1) && (!state.building || card.dataset.building === state.building) && (!state.floor || floorLabel(card.dataset.floor) === state.floor) && (!state.rooms || card.dataset.rooms === state.rooms);
            card.classList.toggle('is-hidden', !ok);
            if (ok) visible += 1;
          });
          count.textContent = 'Talált lakások: ' + visible + ' db';
          empty.classList.toggle('is-visible', visible === 0);
        }
        root.addEventListener('click', function(event){
          var status = event.target.closest('[data-status]');
          if (status) { state.status = status.dataset.status; apply(); return; }
          if (event.target.closest('.harmat-unified-clear')) { state = { status:'all', query:'', building:'', floor:'', rooms:'' }; root.querySelectorAll('[data-filter]').forEach(function(field){ field.value = ''; }); apply(); }
        });
        root.addEventListener('input', function(event){ var field = event.target.closest('[data-filter]'); if (!field) return; state[field.dataset.filter] = field.dataset.filter === 'query' ? field.value.trim().toLowerCase() : field.value; apply(); });
        root.addEventListener('change', function(event){ var field = event.target.closest('[data-filter]'); if (!field) return; state[field.dataset.filter] = field.value; apply(); });
        apply();
      }
      if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', render); else render();
      setTimeout(render, 600);
      setTimeout(render, 1600);
    })();
    </script>
